"use client";
import { FormEvent, useState } from "react";
import { useRouter } from "next/navigation";
import { api } from "../../lib/api";
export function AuthForm(){const [email,setEmail]=useState("admin@cit.local"),[password,setPassword]=useState("TechZephyr!2026"),[error,setError]=useState(""),[busy,setBusy]=useState(false);const router=useRouter();async function submit(e:FormEvent){e.preventDefault();setError("");setBusy(true);const r=await api<{accessToken:string;refreshToken:string;role:string}>("/api/v1/auth/login",{method:"POST",body:JSON.stringify({email,password})});setBusy(false);if(!r.data){setError(r.error??"Unable to sign in");return}localStorage.setItem("tz_access_token",r.data.accessToken);localStorage.setItem("tz_refresh_token",r.data.refreshToken);localStorage.setItem("tz_role",r.data.role);router.replace("/")}return <form className="auth" onSubmit={submit}><p className="eyebrow">CIT SCHEDULING PLATFORM</p><h1>Welcome back.</h1><label>Email<input value={email} onChange={e=>setEmail(e.target.value)} type="email" required/></label><label>Password<input value={password} onChange={e=>setPassword(e.target.value)} type="password" required/></label>{error&&<p className="error">{error}</p>}<button className="primary" disabled={busy}>{busy?"Signing in…":"Sign in"} <span>→</span></button></form>}
